{
  "query": "query ListHalls($locale: I18NLocaleCode, $status: PublicationStatus) {
  halls(locale: $locale, status: $status, sort: ["sortOrder:asc"]) {
    documentId
    name
    slug
    description
    capacity
    quantityLabel
    priceForFullyBooking
    minimumPersonCountForBooking
    isActive
    sortOrder
    publishedAt
    mainImage { url name }
    images { url name }
    hallStats { label value }
    eventTypes { name }
  }
}",
  "variables": {
    "locale": "{{locale}}",
    "status": "PUBLISHED"
  }
}

{
  "query": "query GetHall($documentId: ID!, $locale: I18NLocaleCode) {
  hall(documentId: $documentId, locale: $locale) {
    documentId
    name
    slug
    description
    longDescription
    capacity
    quantityLabel
    priceForFullyBooking
    minimumPersonCountForBooking
    isActive
    sortOrder
    publishedAt
    mainImage { url name width height }
    images { url name }
    hallStats { label value }
    eventTypes { name }
  }
}",
  "variables": {
    "documentId": "REPLACE_WITH_DOCUMENT_ID",
    "locale": "{{locale}}"
  }
}

{
  "query": "mutation CreateHall($data: HallInput!) {\n  createHall(data: $data) {\n    documentId\n    name\n    slug\n    publishedAt\n  }\n}",
  "variables": {
    "data": {
      "name": "Grand Hall",
      "description": "Spacious hall for large events",
      "longDescription": "<p>Full description...</p>",
      "capacity": "200-300",
      "quantityLabel": "guests",
      "priceForFullyBooking": 5000,
      "minimumPersonCountForBooking": 50,
      "isActive": true,
      "sortOrder": 1,
      "locale": "{{locale}}",
      "hallStats": [
        { "label": "Area", "value": "500 m2" },
        { "label": "Height", "value": "5 m" }
      ],
      "eventTypes": [
        { "name": "Wedding" },
        { "name": "Corporate" }
      ]
    }
  }
}

{
  "query": "mutation UpdateHall($documentId: ID!, $data: HallInput!) {\n  updateHall(documentId: $documentId, data: $data) {\n    documentId\n    name\n    slug\n    capacity\n  }\n}",
  "variables": {
    "documentId": "REPLACE_WITH_DOCUMENT_ID",
    "data": {
      "name": "Grand Hall (Updated)",
      "capacity": "250-350",
      "priceForFullyBooking": 6000,
      "sortOrder": 1
    }
  }
}

{
  "query": "mutation PublishHall($documentId: ID!) {
  publishHall(documentId: $documentId) {
    documentId
    name
    publishedAt
  }
}",
  "variables": {
    "documentId": "REPLACE_WITH_DOCUMENT_ID"
  }
}

{
  "query": "mutation UnpublishHall($documentId: ID!) {
  unpublishHall(documentId: $documentId) {
